package com.parevetimer.app;
import android.content.Context;import android.graphics.*;import android.util.AttributeSet;import android.view.View;
public class ProgressRingView extends View{private final Paint track=new Paint(3),progress=new Paint(3);private float p=1f;public ProgressRingView(Context c,AttributeSet a){super(c,a);track.setStyle(Paint.Style.STROKE);progress.setStyle(Paint.Style.STROKE);track.setStrokeWidth(18);progress.setStrokeWidth(18);track.setStrokeCap(Paint.Cap.ROUND);progress.setStrokeCap(Paint.Cap.ROUND);track.setColor(0xFFE6EBF3);progress.setColor(0xFF315FAE);}public void setProgress(float v){p=Math.max(0,Math.min(1,v));invalidate();}@Override protected void onDraw(Canvas c){float s=Math.min(getWidth(),getHeight())-22,left=(getWidth()-s)/2f,top=(getHeight()-s)/2f;RectF r=new RectF(left,top,left+s,top+s);c.drawArc(r,-90,360,false,track);c.drawArc(r,-90,360*p,false,progress);}}
